import React, { useState, useEffect } from 'react';

export default function StudentDashboard({ userName, userId, handleLogout }) {
  const [activeMenu, setActiveMenu] = useState('Dashboard');
  const [studentDetails, setStudentDetails] = useState(null);

  useEffect(() => {
    setStudentDetails({
      regNo: userId || "AP/ST/2026/01",
      course: "Primary Education (Grade 6)"
    });
  }, [userId]);

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 AURA PEN GREEN SIDEBAR */}
      <div style={{ width: '260px', backgroundColor: '#15803d', color: '#fff', display: 'flex', flexDirection: 'column', padding: '20px 0', boxShadow: '4px 0 10px rgba(0,0,0,0.05)' }}>
        <div style={{ padding: '0 20px 20px 20px', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '20px' }}>
          <h2 style={{ margin: 0, color: '#fff', fontSize: '22px', fontWeight: '800' }}>AURA PEN</h2>
          <span style={{ fontSize: '11px', color: '#dcfce7', opacity: 0.9, fontWeight: '600' }}>STUDENT LMS PORTAL</span>
        </div>

        <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '5px' }}>
          {[
            { id: 'Dashboard', label: '📊 Dashboard' },
            { id: 'My Subjects', label: '📚 My Subjects' },
            { id: 'Online Quizzes', label: '📝 Online Quizzes' },
            { id: 'Quiz Results', label: '🏆 Quiz Results' },
            { id: 'Notifications', label: '🔔 Notifications' },
            { id: 'Discussion Forum', label: '💬 Discussion Forum' },
            { id: 'Feedback', label: '⭐ Feedback' },
            { id: 'My Profile', label: '👤 My Profile' }
          ].map(item => (
            <button
              key={item.id}
              onClick={() => setActiveMenu(item.id)}
              style={{
                width: '100%', padding: '14px 20px', border: 'none',
                backgroundColor: activeMenu === item.id ? '#166534' : 'transparent',
                color: '#fff', fontSize: '14px', fontWeight: '600', cursor: 'pointer',
                textAlign: 'left', transition: '0.2s', borderLeft: activeMenu === item.id ? '5px solid #38bdf8' : '5px solid transparent'
              }}
            >
              {item.label}
            </button>
          ))}
        </div>

        <div style={{ padding: '20px' }}>
          <button onClick={handleLogout} style={{ width: '100%', backgroundColor: 'transparent', border: '1px solid #fff', color: '#fff', padding: '10px', borderRadius: '6px', fontWeight: '700', cursor: 'pointer' }}>
            🛑 Logout
          </button>
        </div>
      </div>

      {/* ⚪ MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '35px', overflowY: 'auto' }}>
        
        {/* Welcome Banner */}
        <div style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '16px', boxShadow: '0 4px 20px rgba(0,0,0,0.02)', borderLeft: '6px solid #15803d', marginBottom: '30px', border: '1px solid #e2e8f0', borderLeftWidth: '6px' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', fontWeight: '700' }}>👑 Welcome, {userName || "Student"}</h2>
          <p style={{ margin: '5px 0 0 0', color: '#64748b', fontSize: '14px', fontWeight: '500' }}>Registration No: <span style={{ color: '#15803d', fontWeight: '700' }}>{studentDetails?.regNo}</span></p>
        </div>

        {/* 📊 4 Analytics Cards */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '20px', marginBottom: '35px' }}>
          
          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
            <span style={{ fontSize: '13px', color: '#0369a1', fontWeight: '750', backgroundColor: '#e0f2fe', padding: '4px 8px', borderRadius: '6px' }}>🔹 Enrolled Courses</span>
            <h1 style={{ margin: '15px 0 0 0', fontSize: '36px', color: '#1e293b', fontWeight: '800' }}>1</h1>
          </div>

          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
            <span style={{ fontSize: '13px', color: '#15803d', fontWeight: '750', backgroundColor: '#dcfce7', padding: '4px 8px', borderRadius: '6px' }}>📖 Total Subjects</span>
            <h1 style={{ margin: '15px 0 0 0', fontSize: '36px', color: '#1e293b', fontWeight: '800' }}>1</h1>
          </div>

          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
            <span style={{ fontSize: '13px', color: '#0369a1', fontWeight: '750', backgroundColor: '#e0f2fe', padding: '4px 8px', borderRadius: '6px' }}>📄 Learning Materials</span>
            <h1 style={{ margin: '15px 0 0 0', fontSize: '36px', color: '#1e293b', fontWeight: '800' }}>1</h1>
          </div>

          <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
            <span style={{ fontSize: '13px', color: '#b45309', fontWeight: '750', backgroundColor: '#fef3c7', padding: '4px 8px', borderRadius: '6px' }}>📝 Total Quizzes</span>
            <h1 style={{ margin: '15px 0 0 0', fontSize: '36px', color: '#1e293b', fontWeight: '800' }}>2</h1>
          </div>

        </div>

        {/* 📘 Academic Courses Section */}
        <div style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
          <h3 style={{ margin: '0 0 20px 0', color: '#15803d', fontSize: '18px', fontWeight: '700' }}>🔷 My Academic Courses</h3>
          
          <div style={{ padding: '22px', border: '1px solid #e2e8f0', borderRadius: '12px', maxWidth: '360px', backgroundColor: '#fafafa' }}>
            <h4 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: '700' }}>{studentDetails?.course}</h4>
            <span style={{ display: 'inline-block', backgroundColor: '#e0f2fe', color: '#0369a1', padding: '4px 8px', borderRadius: '4px', fontSize: '12px', fontWeight: '700', marginTop: '8px' }}>Aura Pen Primary Core</span>
            
            <button style={{ width: '100%', marginTop: '20px', backgroundColor: '#15803d', color: '#fff', border: 'none', padding: '12px', borderRadius: '6px', fontWeight: '600', cursor: 'pointer' }}>
              📁 View Class Materials
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}
